/* Research Finder — Summer 2027
 *
 * Vanilla JS, no build step, no dependencies. Program data comes from
 * data/programs.json (generated by scripts/build.py). Application progress
 * lives in this browser's localStorage and never leaves the device.
 */

(() => {
  "use strict";

  const STORE_KEY = "jolene-s27:tracker:v1";
  const THEME_KEY = "jolene-s27:theme";

  const STATUSES = [
    ["not-started", "Not started"],
    ["drafting", "Drafting"],
    ["submitted", "Submitted"],
    ["interview", "Interview"],
    ["accepted", "Accepted"],
    ["rejected", "Not this time"],
  ];

  const REQUIREMENT_LABELS = {
    transcript: "Transcript (unofficial is usually fine)",
    cv: "CV / resume",
    "personal-statement": "Personal statement",
    "1-lor": "1 letter of recommendation",
    "2-lor": "2 letters of recommendation",
    "3-lor": "3 letters of recommendation",
  };

  const TRACK_LABELS = {
    pediatrics: "Pediatrics",
    oncology: "Oncology / cancer",
    neuroscience: "Neuroscience",
    alzheimers: "Alzheimer's / dementia",
    clinical: "Clinical research",
    "basic-science": "Basic science / bench",
    translational: "Translational",
    cardiovascular: "Cardiovascular",
    genomics: "Genomics",
    immunology: "Immunology",
    developmental: "Developmental biology",
    neonatal: "Neonatal",
    psychology: "Psychology",
    autism: "Autism",
    aging: "Aging",
    computational: "Computational",
    bioengineering: "Bioengineering",
    "public-health": "Public health",
    "emergency-medicine": "Emergency medicine",
    "stem-cell": "Stem cell",
    chemistry: "Chemistry",
    "pre-health": "Pre-health enrichment",
  };

  const HOUSING_LABELS = {
    provided: "Housing provided",
    "provided-nonlocal": "Housing for non-locals",
    "not-provided": "No housing",
    varies: "Housing varies",
    "stipend-covers": "Stipend covers housing",
  };

  const CITIZENSHIP_LABELS = {
    "us-or-pr": "US citizen or permanent resident",
    "us-pr-or-f1": "US citizen, permanent resident or F-1",
    unspecified: "Not stated",
  };

  const SELECTIVITY_LABELS = {
    "very-high": "Very competitive",
    high: "Competitive",
    moderate: "More attainable",
  };

  // ---------------------------------------------------------------- state

  let DATA = { programs: [], cycle: "", generated: "" };
  let tracker = loadTracker();
  let view = "plan";
  let query = "";
  let sortBy = "deadline";
  const filters = { track: new Set(), month: new Set(), housing: new Set(), selectivity: new Set(), flags: new Set() };

  const TODAY = startOfDay(new Date());

  // ---------------------------------------------------------------- helpers

  function startOfDay(d) {
    return new Date(d.getFullYear(), d.getMonth(), d.getDate());
  }

  function parseDate(value) {
    if (!value) return null;
    const [y, m, d] = value.split("-").map(Number);
    if (!y || !m || !d) return null;
    return new Date(y, m - 1, d);
  }

  function daysBetween(from, to) {
    return Math.round((to - from) / 86400000);
  }

  function fmtDate(value, opts) {
    const d = parseDate(value);
    if (!d) return "—";
    return d.toLocaleDateString(undefined, opts || { month: "short", day: "numeric" });
  }

  function fmtMoney(n) {
    if (!n) return null;
    return "$" + n.toLocaleString();
  }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]
    );
  }

  function el(html) {
    const t = document.createElement("template");
    t.innerHTML = html.trim();
    return t.content.firstElementChild;
  }

  function monthKey(value) {
    const d = parseDate(value);
    if (!d) return null;
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
  }

  function monthLabel(key) {
    const [y, m] = key.split("-").map(Number);
    return new Date(y, m - 1, 1).toLocaleDateString(undefined, { month: "long", year: "numeric" });
  }

  // ---------------------------------------------------------------- tracker

  function loadTracker() {
    try {
      const raw = localStorage.getItem(STORE_KEY);
      if (!raw) return { version: 1, items: {} };
      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== "object" || !parsed.items) return { version: 1, items: {} };
      return parsed;
    } catch (err) {
      return { version: 1, items: {} };
    }
  }

  function saveTracker() {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(tracker));
    } catch (err) {
      /* private mode or blocked storage: the page still works, just forgets. */
    }
  }

  function entry(id) {
    if (!tracker.items[id]) tracker.items[id] = { status: "not-started", notes: "", done: {} };
    return tracker.items[id];
  }

  function statusOf(id) {
    const item = tracker.items[id];
    return item && item.status ? item.status : "not-started";
  }

  function setStatus(id, status) {
    entry(id).status = status;
    entry(id).updated = new Date().toISOString();
    saveTracker();
  }

  function isActive(id) {
    const s = statusOf(id);
    return s !== "rejected" && s !== "accepted";
  }

  // ---------------------------------------------------------------- urgency

  /* One program can be in several situations at once: not open yet, open and
   * due soon, or past its date. This collapses that into a single label plus a
   * colour tier used by both the cards and the plan. */
  function urgency(p) {
    const opens = parseDate(p.opens);
    const deadline = parseDate(p.deadline);
    const est = p.deadline_status !== "confirmed";

    if (p.deadline_status === "rolling") {
      return { tier: "idle", label: "Rolling", sort: 8000, phase: "rolling" };
    }

    if (opens && opens > TODAY) {
      const d = daysBetween(TODAY, opens);
      return {
        tier: d <= 21 ? "soon" : "idle",
        label: d === 0 ? "Opens today" : `Opens in ${d}d`,
        sort: 1000 + d,
        phase: "upcoming",
        est,
      };
    }

    if (deadline) {
      const d = daysBetween(TODAY, deadline);
      if (d < 0) {
        return { tier: "idle", label: `Closed ${Math.abs(d)}d ago`, sort: 9000, phase: "closed", est };
      }
      let tier = "calm";
      if (d <= 14) tier = "urgent";
      else if (d <= 35) tier = "soon";
      return {
        tier,
        label: d === 0 ? "Due today" : `Due in ${d}d`,
        sort: d,
        phase: "open",
        est,
      };
    }

    return { tier: "idle", label: "Date not posted", sort: 7000, phase: "unknown" };
  }

  // ---------------------------------------------------------------- filtering

  function matchesQuery(p) {
    if (!query) return true;
    const hay = [p.name, p.org, p.city, p.focus, p.notes, (p.tracks || []).join(" ")]
      .join(" ")
      .toLowerCase();
    return query.split(/\s+/).every((word) => hay.includes(word));
  }

  function passesFilters(p) {
    if (filters.track.size && !(p.tracks || []).some((t) => filters.track.has(t))) return false;
    if (filters.housing.size && !filters.housing.has(p.housing)) return false;
    if (filters.selectivity.size && !filters.selectivity.has(p.selectivity)) return false;

    if (filters.month.size) {
      const key = monthKey(p.deadline);
      if (!key || !filters.month.has(key)) return false;
    }

    for (const flag of filters.flags) {
      if (flag === "stipend" && !p.stipend_usd) return false;
      if (flag === "housing" && !["provided", "provided-nonlocal", "stipend-covers"].includes(p.housing)) return false;
      if (flag === "confirmed" && p.deadline_status !== "confirmed") return false;
      if (flag === "open-now" && urgency(p).phase !== "open") return false;
      if (flag === "top-pick" && p.priority_hint !== "top-pick") return false;
      if (flag === "no-citizenship" && p.eligibility && p.eligibility.citizenship === "us-or-pr") return false;
    }
    return true;
  }

  function visibleProgramsForBrowse() {
    const list = DATA.programs.filter((p) => matchesQuery(p) && passesFilters(p));
    const cmp = {
      deadline: (a, b) => urgency(a).sort - urgency(b).sort || a.name.localeCompare(b.name),
      opens: (a, b) => (a.opens || "9999").localeCompare(b.opens || "9999") || a.name.localeCompare(b.name),
      stipend: (a, b) => (b.stipend_usd || 0) - (a.stipend_usd || 0) || a.name.localeCompare(b.name),
      name: (a, b) => a.name.localeCompare(b.name),
      org: (a, b) => a.org.localeCompare(b.org) || a.name.localeCompare(b.name),
    }[sortBy];
    return list.sort(cmp);
  }

  // ---------------------------------------------------------------- cards

  function pill(tier, label, est) {
    return `<span class="pill pill--${tier}">${esc(label)}${est ? ' <span class="est">est.</span>' : ""}</span>`;
  }

  function statusSelect(id) {
    const current = statusOf(id);
    const opts = STATUSES.map(
      ([value, label]) =>
        `<option value="${value}"${value === current ? " selected" : ""}>${esc(label)}</option>`
    ).join("");
    return `<select class="status" data-status-for="${esc(id)}" data-value="${current}" aria-label="Application status">${opts}</select>`;
  }

  function card(p) {
    const u = urgency(p);
    const edge = { urgent: "var(--urgent)", soon: "var(--soon)", calm: "var(--calm)", idle: "var(--line-strong)" }[u.tier];
    const done = ["accepted", "rejected"].includes(statusOf(p.id));

    const facts = [];
    if (p.duration_weeks) facts.push(`${p.duration_weeks} weeks`);
    if (p.stipend_usd) facts.push(fmtMoney(p.stipend_usd));
    if (p.housing && p.housing !== "not-provided" && p.housing !== "varies") {
      facts.push(HOUSING_LABELS[p.housing]);
    }
    if (p.eligibility && p.eligibility.min_gpa) facts.push(`GPA ${p.eligibility.min_gpa}+`);

    const tags = (p.tracks || []).slice(0, 3).map((t) => `<span class="tag">${esc(TRACK_LABELS[t] || t)}</span>`).join(" ");

    return el(`
      <article class="card${done ? " card--done" : ""}" style="--edge:${edge}" data-id="${esc(p.id)}">
        <div class="card__top">
          <div class="card__name">
            <a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.name)}</a>
          </div>
          ${pill(u.tier, u.label, u.est)}
        </div>
        <div>
          <div class="card__org">${esc(p.org)}</div>
          <div class="card__where">${esc(p.city)}${p.priority_hint === "top-pick" ? " · <strong>top pick</strong>" : ""}</div>
        </div>
        <p class="card__focus">${esc(p.focus)}</p>
        <div class="card__facts">${facts.map((f) => `<span>${esc(f)}</span>`).join('<span class="sep">·</span>')}</div>
        <div>${tags}</div>
        <div class="card__foot">
          <button class="icon-btn" data-open-detail="${esc(p.id)}" type="button">Details</button>
          ${statusSelect(p.id)}
        </div>
      </article>
    `);
  }

  function row(p, whenText, whenTier) {
    const u = urgency(p);
    return el(`
      <div class="row" data-id="${esc(p.id)}">
        <div class="row__when" style="color:var(--${whenTier === "idle" ? "ink-faint" : whenTier})">${esc(whenText)}</div>
        <div class="row__main">
          <div class="row__name"><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.name)}</a></div>
          <div class="row__sub">${esc(p.org)} · ${esc(p.city)}</div>
        </div>
        ${pill(u.tier, u.label, u.est)}
        <button class="icon-btn" data-open-detail="${esc(p.id)}" type="button">Details</button>
        ${statusSelect(p.id)}
      </div>
    `);
  }

  // ---------------------------------------------------------------- plan view

  function renderPlan() {
    const stats = document.getElementById("plan-stats");
    const blocks = document.getElementById("plan-blocks");
    stats.textContent = "";
    blocks.textContent = "";

    const open = DATA.programs.filter((p) => urgency(p).phase === "open" && isActive(p.id));
    const submitted = DATA.programs.filter((p) => ["submitted", "interview", "accepted"].includes(statusOf(p.id)));
    const next = open.slice().sort((a, b) => urgency(a).sort - urgency(b).sort)[0];
    const within30 = open.filter((p) => urgency(p).sort <= 30);

    const cards = [
      [DATA.programs.length, "programs tracked"],
      [open.length, "accepting now"],
      [within30.length, "due within 30 days"],
      [submitted.length, "you have submitted"],
      [next ? fmtDate(next.deadline) : "—", "next deadline"],
    ];
    cards.forEach(([n, k]) => {
      stats.appendChild(el(`<div class="stat"><div class="stat__n">${esc(n)}</div><div class="stat__k">${esc(k)}</div></div>`));
    });

    const topPicks = DATA.programs.filter((p) => p.priority_hint === "top-pick");
    const openNow = DATA.programs.filter((p) => p.priority_hint === "open-now");
    const opening = DATA.programs
      .filter((p) => urgency(p).phase === "upcoming")
      .sort((a, b) => (a.opens || "").localeCompare(b.opens || ""));
    const portals = DATA.programs.filter((p) => p.priority_hint === "portal");
    const needsInput = DATA.programs.filter((p) => p.needs_input);
    const lateBackups = DATA.programs.filter((p) => p.priority_hint === "late-backup");

    function block(title, note, list, whenFn) {
      if (!list.length) return;
      const wrap = el(`
        <section class="block">
          <div class="block__head"><h2>${esc(title)}</h2><span class="n">${list.length}</span></div>
          ${note ? `<p class="block__note">${note}</p>` : ""}
          <div class="rows"></div>
        </section>
      `);
      const rows = wrap.querySelector(".rows");
      list.forEach((p) => {
        const w = whenFn(p);
        rows.appendChild(row(p, w.text, w.tier));
      });
      blocks.appendChild(wrap);
    }

    // Everything currently accepting applications, with the ones flagged on the
    // original list as already open pulled to the front.
    const acceptingNow = open
      .slice()
      .sort(
        (a, b) =>
          (b.priority_hint === "open-now") - (a.priority_hint === "open-now") ||
          urgency(a).sort - urgency(b).sort
      );

    block(
      "Start here — accepting applications now",
      "Nothing is blocking these: the portal is open today. Every day one sits untouched is a day " +
        "of free optionality thrown away.",
      acceptingNow,
      (p) => ({ text: "Due " + fmtDate(p.deadline), tier: urgency(p).tier })
    );

    block(
      "Highest-value applications",
      "Ranked for a rising senior aiming at pediatric and neuro research. Four of these are " +
        "<em>one application, many labs or institutions</em> — the best return on a single essay you will find: " +
        "NIH SIP, Amgen Scholars, the Leadership Alliance and Vanderbilt's umbrella program. " +
        "Fred Hutch is here because it is restricted to rising seniors, which is exactly her year.",
      topPicks,
      (p) => ({ text: "Due " + fmtDate(p.deadline), tier: urgency(p).tier })
    );

    block(
      "Due in the next 30 days",
      "Sorted by how little time is left.",
      within30.sort((a, b) => urgency(a).sort - urgency(b).sort),
      (p) => ({ text: urgency(p).label, tier: urgency(p).tier })
    );

    block(
      "Opens soon — put a reminder down",
      "Nothing to do yet except be ready. The repo's watcher checks these pages weekly and will " +
        "flag the moment the Summer 2027 details appear.",
      opening.slice(0, 14),
      (p) => ({ text: "Opens " + fmtDate(p.opens), tier: urgency(p).tier })
    );

    block(
      "Sweep these monthly",
      "Not single programs but directories, each covering dozens or hundreds of openings. " +
        "Half an hour here beats an hour on any one application.",
      portals,
      () => ({ text: "Monthly", tier: "idle" })
    );

    block(
      "Late deadlines — keep as insurance",
      "If February brings bad news, these are still open.",
      lateBackups,
      (p) => ({ text: "Due " + fmtDate(p.deadline), tier: urgency(p).tier })
    );

    block(
      "Needs a link from the original list",
      "Two entries came across without an institution, so they could not be identified. " +
        "Finding the original Notion link takes a minute and the entry can then be filled in.",
      needsInput,
      () => ({ text: "Action", tier: "soon" })
    );
  }

  // ---------------------------------------------------------------- browse view

  function renderFilters() {
    const body = document.getElementById("filters-body");
    body.textContent = "";

    const counts = (key, getter) => {
      const map = new Map();
      DATA.programs.forEach((p) => {
        const values = getter(p);
        (Array.isArray(values) ? values : [values]).forEach((v) => {
          if (v == null) return;
          map.set(v, (map.get(v) || 0) + 1);
        });
      });
      return map;
    };

    function group(title, name, entries, labelFor) {
      if (!entries.length) return;
      const g = el(`<div class="fgroup"><h3>${esc(title)}</h3></div>`);
      entries.forEach(([value, n]) => {
        const checked = filters[name].has(value) ? " checked" : "";
        const label = el(`
          <label class="check">
            <input type="checkbox" data-filter="${esc(name)}" value="${esc(value)}"${checked}>
            <span>${esc(labelFor ? labelFor(value) : value)}</span>
            <span class="tally">${n}</span>
          </label>
        `);
        g.appendChild(label);
      });
      body.appendChild(g);
    }

    group(
      "Quick filters",
      "flags",
      [
        ["top-pick", DATA.programs.filter((p) => p.priority_hint === "top-pick").length],
        ["open-now", DATA.programs.filter((p) => urgency(p).phase === "open").length],
        ["confirmed", DATA.programs.filter((p) => p.deadline_status === "confirmed").length],
        ["stipend", DATA.programs.filter((p) => p.stipend_usd).length],
        ["housing", DATA.programs.filter((p) => ["provided", "provided-nonlocal", "stipend-covers"].includes(p.housing)).length],
        ["no-citizenship", DATA.programs.filter((p) => !p.eligibility || p.eligibility.citizenship !== "us-or-pr").length],
      ],
      (v) =>
        ({
          "top-pick": "Top picks only",
          "open-now": "Accepting now",
          confirmed: "Date confirmed",
          stipend: "Paid stipend",
          housing: "Housing included",
          "no-citizenship": "No US-citizen rule",
        }[v] || v)
    );

    const trackCounts = [...counts("track", (p) => p.tracks)].sort((a, b) => b[1] - a[1]);
    group("Research area", "track", trackCounts, (v) => TRACK_LABELS[v] || v);

    const monthCounts = [...counts("month", (p) => monthKey(p.deadline))].sort((a, b) => a[0].localeCompare(b[0]));
    group("Deadline month", "month", monthCounts, monthLabel);

    const housingCounts = [...counts("housing", (p) => p.housing)].sort((a, b) => b[1] - a[1]);
    group("Housing", "housing", housingCounts, (v) => HOUSING_LABELS[v] || v);

    const selCounts = [...counts("selectivity", (p) => p.selectivity)].sort((a, b) => b[1] - a[1]);
    group("Odds", "selectivity", selCounts, (v) => SELECTIVITY_LABELS[v] || v);
  }

  function renderBrowse() {
    const grid = document.getElementById("browse-grid");
    const list = visibleProgramsForBrowse();
    grid.textContent = "";

    document.getElementById("browse-count").innerHTML =
      `<strong>${list.length}</strong> of ${DATA.programs.length} programs`;

    if (!list.length) {
      grid.appendChild(
        el(`<div class="empty"><h3>Nothing matches</h3><p>Try clearing a filter or shortening the search.</p></div>`)
      );
      return;
    }
    const frag = document.createDocumentFragment();
    list.forEach((p) => frag.appendChild(card(p)));
    grid.appendChild(frag);
  }

  // ---------------------------------------------------------------- tracker view

  function renderTracker() {
    const stats = document.getElementById("tracker-stats");
    const blocks = document.getElementById("tracker-blocks");
    stats.textContent = "";
    blocks.textContent = "";

    const byStatus = new Map(STATUSES.map(([v]) => [v, []]));
    DATA.programs.forEach((p) => {
      const s = statusOf(p.id);
      if (byStatus.has(s)) byStatus.get(s).push(p);
    });

    const touched = DATA.programs.length - byStatus.get("not-started").length;

    STATUSES.filter(([v]) => v !== "not-started").forEach(([value, label]) => {
      stats.appendChild(
        el(`<div class="stat"><div class="stat__n">${byStatus.get(value).length}</div><div class="stat__k">${esc(label)}</div></div>`)
      );
    });

    if (!touched) {
      blocks.appendChild(
        el(`
        <div class="empty">
          <h3>Nothing marked yet</h3>
          <p>Set a status on any program — from a card, or from the details panel — and it shows up here.<br>
          Everything is stored in this browser only, so use <strong>Backup</strong> in the header before clearing cookies.</p>
        </div>
      `)
      );
      return;
    }

    STATUSES.forEach(([value, label]) => {
      const list = byStatus.get(value);
      if (!list.length || value === "not-started") return;
      list.sort((a, b) => urgency(a).sort - urgency(b).sort);
      const wrap = el(`
        <section class="block">
          <div class="block__head"><h2>${esc(label)}</h2><span class="n">${list.length}</span></div>
          <div class="rows"></div>
        </section>
      `);
      const rows = wrap.querySelector(".rows");
      list.forEach((p) => rows.appendChild(row(p, fmtDate(p.deadline), urgency(p).tier)));
      blocks.appendChild(wrap);
    });
  }

  // ---------------------------------------------------------------- timeline view

  function renderCalendar() {
    const host = document.getElementById("calendar-rows");
    host.textContent = "";

    const events = [];
    DATA.programs.forEach((p) => {
      if (p.opens) events.push({ p, date: p.opens, kind: "opens" });
      if (p.deadline) events.push({ p, date: p.deadline, kind: "deadline" });
    });
    events.sort((a, b) => a.date.localeCompare(b.date) || a.p.name.localeCompare(b.p.name));

    let lastMonth = null;
    events.forEach(({ p, date, kind }) => {
      const key = monthKey(date);
      if (key !== lastMonth) {
        lastMonth = key;
        host.appendChild(
          el(`<div class="row" style="background:var(--bg-sunken)"><div class="row__when" style="width:auto;font-weight:680">${esc(monthLabel(key))}</div></div>`)
        );
      }
      const tier = kind === "deadline" ? urgency(p).tier : "idle";
      const verb = kind === "deadline" ? "Due" : "Opens";
      host.appendChild(row(p, `${verb} ${fmtDate(date)}`, tier));
    });
  }

  // ---------------------------------------------------------------- drawer

  let lastFocus = null;

  function openDetail(id) {
    const p = DATA.programs.find((x) => x.id === id);
    if (!p) return;

    lastFocus = document.activeElement;
    const u = urgency(p);
    const e = entry(p.id);
    const elig = p.eligibility || {};

    const rows = [
      ["Institution", p.org],
      ["Location", p.city],
      ["Deadline", p.deadline ? `${fmtDate(p.deadline, { month: "long", day: "numeric", year: "numeric" })}${p.deadline_status === "confirmed" ? "" : " (projected)"}` : "not posted"],
      ["Opens", p.opens ? fmtDate(p.opens, { month: "long", day: "numeric", year: "numeric" }) : "unknown"],
      ["Length", p.duration_weeks ? `${p.duration_weeks} weeks` : "—"],
      ["Stipend", p.stipend_note || fmtMoney(p.stipend_usd) || "not stated"],
      ["Housing", HOUSING_LABELS[p.housing] || p.housing],
      ["Odds", SELECTIVITY_LABELS[p.selectivity] || p.selectivity],
      ["Citizenship", CITIZENSHIP_LABELS[elig.citizenship] || elig.citizenship || "—"],
      ["Min GPA", elig.min_gpa ? String(elig.min_gpa) : "none stated"],
      ["Class years", (elig.class_years || []).join(", ") || "—"],
      ["Area", (p.tracks || []).map((t) => TRACK_LABELS[t] || t).join(", ")],
    ];

    const checklist = (p.requires || [])
      .map((req) => {
        const checked = e.done && e.done[req];
        return `<li><label class="${checked ? "is-done" : ""}">
          <input type="checkbox" data-req="${esc(req)}" data-req-for="${esc(p.id)}"${checked ? " checked" : ""}>
          <span>${esc(REQUIREMENT_LABELS[req] || req)}</span>
        </label></li>`;
      })
      .join("");

    const body = document.getElementById("drawer-body");
    document.getElementById("drawer-title").textContent = p.name;

    body.innerHTML = `
      <div style="margin-bottom:14px">${pill(u.tier, u.label, u.est)}
        ${p.priority_hint === "top-pick" ? '<span class="pill pill--accent">Top pick</span>' : ""}
        ${p.deadline_status === "confirmed" ? '<span class="pill pill--calm">Date confirmed</span>' : ""}
      </div>

      <p style="font-size:.875rem;color:var(--ink-soft);margin:0 0 16px">${esc(p.focus)}</p>

      ${p.notes ? `<div class="callout callout--accent">${esc(p.notes)}</div>` : ""}
      ${p.deadline_status === "projected" ? `<div class="callout">This date is projected from an earlier cycle. Confirm it on the program page before relying on it.</div>` : ""}
      ${p.link_note ? `<div class="callout">${esc(p.link_note)}</div>` : ""}
      ${elig.notes ? `<div class="callout callout--accent"><strong>Eligibility:</strong> ${esc(elig.notes)}</div>` : ""}

      <a class="btn btn--block" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer" style="margin-bottom:18px">
        Open the program page
      </a>

      <h3>Facts</h3>
      <dl>${rows.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join("")}</dl>

      ${checklist ? `<h3>What they ask for</h3><ul class="checklist">${checklist}</ul>` : ""}

      <h3>Status</h3>
      <div style="margin-bottom:18px">${statusSelect(p.id)}</div>

      <h3>My notes</h3>
      <textarea class="drawer__note" data-note-for="${esc(p.id)}"
        placeholder="Who you emailed, which lab you want, portal login, anything to remember.">${esc(e.notes || "")}</textarea>

      ${p.contact ? `<p style="font-size:.8125rem;color:var(--ink-soft);margin-top:14px">Contact: <a href="mailto:${esc(p.contact)}">${esc(p.contact)}</a></p>` : ""}
    `;

    document.getElementById("drawer").dataset.open = "true";
    document.getElementById("scrim").dataset.open = "true";
    // Stop the page behind the drawer from scrolling along with it.
    document.body.style.overflow = "hidden";
    document.getElementById("drawer").focus();
  }

  function closeDetail() {
    const drawer = document.getElementById("drawer");
    if (drawer.dataset.open !== "true") return;
    drawer.dataset.open = "false";
    document.getElementById("scrim").dataset.open = "false";
    document.body.style.overflow = "";
    if (lastFocus && lastFocus.focus) lastFocus.focus();
  }

  function drawerIsOpen() {
    return document.getElementById("drawer").dataset.open === "true";
  }

  // ---------------------------------------------------------------- render

  function render() {
    ["plan", "browse", "tracker", "calendar"].forEach((name) => {
      document.getElementById("view-" + name).hidden = name !== view;
      const tab = document.getElementById("tab-" + name);
      if (tab) tab.setAttribute("aria-selected", String(name === view));
    });

    if (view === "plan") renderPlan();
    if (view === "browse") renderBrowse();
    if (view === "tracker") renderTracker();
    if (view === "calendar") renderCalendar();

    document.getElementById("count-browse").textContent = DATA.programs.length;
    const touched = Object.values(tracker.items).filter((i) => i.status && i.status !== "not-started").length;
    document.getElementById("count-tracker").textContent = touched || "";
  }

  // ---------------------------------------------------------------- events

  function wire() {
    document.querySelectorAll(".views button").forEach((btn) => {
      btn.addEventListener("click", () => {
        view = btn.dataset.view;
        render();
        window.scrollTo({ top: 0, behavior: "smooth" });
      });
    });

    const search = document.getElementById("q");
    let debounce;
    search.addEventListener("input", () => {
      clearTimeout(debounce);
      debounce = setTimeout(() => {
        query = search.value.trim().toLowerCase();
        if (view !== "browse") {
          view = "browse";
          render();
        } else {
          renderBrowse();
        }
      }, 140);
    });

    document.getElementById("sort").addEventListener("change", (ev) => {
      sortBy = ev.target.value;
      renderBrowse();
    });

    document.getElementById("filters-clear").addEventListener("click", () => {
      Object.values(filters).forEach((set) => set.clear());
      renderFilters();
      renderBrowse();
    });

    const fWrap = document.getElementById("filters");
    document.getElementById("filters-toggle").addEventListener("click", (ev) => {
      const collapsed = fWrap.dataset.collapsed === "true";
      fWrap.dataset.collapsed = String(!collapsed);
      ev.target.textContent = collapsed ? "Hide" : "Show";
    });

    // Filter checkboxes are re-rendered often, so delegate from the container.
    document.getElementById("filters-body").addEventListener("change", (ev) => {
      const input = ev.target.closest("input[data-filter]");
      if (!input) return;
      const set = filters[input.dataset.filter];
      if (input.checked) set.add(input.value);
      else set.delete(input.value);
      renderBrowse();
    });

    // Status selects, detail buttons, checklists and notes all live inside
    // re-rendered markup, so everything is delegated from the document.
    document.addEventListener("change", (ev) => {
      const status = ev.target.closest("select[data-status-for]");
      if (status) {
        setStatus(status.dataset.statusFor, status.value);
        render();
        return;
      }
      const req = ev.target.closest("input[data-req-for]");
      if (req) {
        const e = entry(req.dataset.reqFor);
        e.done = e.done || {};
        e.done[req.dataset.req] = req.checked;
        saveTracker();
        req.closest("label").classList.toggle("is-done", req.checked);
      }
    });

    document.addEventListener("click", (ev) => {
      const open = ev.target.closest("[data-open-detail]");
      if (open) {
        openDetail(open.dataset.openDetail);
        return;
      }
      if (ev.target.closest("#drawer-close") || ev.target.id === "scrim") closeDetail();
    });

    document.addEventListener("input", (ev) => {
      const note = ev.target.closest("textarea[data-note-for]");
      if (!note) return;
      entry(note.dataset.noteFor).notes = note.value;
      clearTimeout(note._t);
      note._t = setTimeout(saveTracker, 350);
    });

    document.addEventListener("keydown", (ev) => {
      if (ev.key === "Escape") closeDetail();
      if (ev.key === "/" && document.activeElement !== search) {
        ev.preventDefault();
        search.focus();
      }
    });

    // theme
    const themeBtn = document.getElementById("theme-toggle");
    try {
      const saved = localStorage.getItem(THEME_KEY);
      if (saved) document.documentElement.dataset.theme = saved;
    } catch (err) { /* ignore */ }

    themeBtn.addEventListener("click", () => {
      const root = document.documentElement;
      const isDark =
        root.dataset.theme === "dark" ||
        (!root.dataset.theme && window.matchMedia("(prefers-color-scheme: dark)").matches);
      root.dataset.theme = isDark ? "light" : "dark";
      try {
        localStorage.setItem(THEME_KEY, root.dataset.theme);
      } catch (err) { /* ignore */ }
    });

    // backup / restore
    document.getElementById("export-btn").addEventListener("click", () => {
      const blob = new Blob([JSON.stringify(tracker, null, 2)], { type: "application/json" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = `research-tracker-${new Date().toISOString().slice(0, 10)}.json`;
      a.click();
      URL.revokeObjectURL(a.href);
    });

    const fileInput = document.getElementById("import-file");
    document.getElementById("import-btn").addEventListener("click", () => fileInput.click());
    fileInput.addEventListener("change", () => {
      const file = fileInput.files && fileInput.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        try {
          const parsed = JSON.parse(String(reader.result));
          if (!parsed || !parsed.items) throw new Error("not a tracker backup");
          const count = Object.keys(parsed.items).length;
          if (confirm(`Restore ${count} tracked programs? This replaces what is in this browser now.`)) {
            tracker = parsed;
            saveTracker();
            render();
          }
        } catch (err) {
          alert("That file could not be read as a tracker backup.");
        }
        fileInput.value = "";
      };
      reader.readAsText(file);
    });
  }

  // ---------------------------------------------------------------- boot

  fetch("data/programs.json", { cache: "no-cache" })
    .then((r) => {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    })
    .then((payload) => {
      DATA = payload;
      document.getElementById("loading").remove();
      document.getElementById("cycle-badge").textContent = payload.cycle || "Summer 2027";
      document.getElementById("footer-meta").textContent =
        `${payload.count} programs · data built ${(payload.generated || "").slice(0, 10)}`;
      renderFilters();
      wire();
      render();
    })
    .catch((err) => {
      const spinner = document.getElementById("loading");
      if (spinner) spinner.remove();
      document.getElementById("main").appendChild(
        el(`<div class="empty"><h3>Could not load the program data</h3>
            <p>${esc(String(err.message || err))}<br>
            If you opened this file directly, serve the folder instead:
            <code>python -m http.server</code> inside <code>site/</code>.</p></div>`)
      );
    });
})();
